 public MotionButton(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint|ControlStyles.ResizeRedraw,true);Cursor=Cursors.Hand;Height=38;Width=140;Font=new Font("Microsoft YaHei UI",9);ForeColor=Color.FromArgb(36,38,40);animation.Interval=15;animation.Tick+=(s,e)=>{hover+=( (over?1f:0f)-hover)*.24f;if(Math.Abs(hover-(over?1:0))<.01){hover=over?1:0;animation.Stop();}Invalidate();};MouseEnter+=(s,e)=>{over=true;if(SystemInformation.IsMenuAnimationEnabled)animation.Start();else{hover=1;Invalidate();}};MouseLeave+=(s,e)=>{over=false;down=false;if(SystemInformation.IsMenuAnimationEnabled)animation.Start();else{hover=0;Invalidate();}Invalidate();};MouseDown+=(s,e)=>{down=true;Invalidate();};MouseUp+=(s,e)=>{down=false;Invalidate();};TabStop=true;}
