public class ChoiceBox:Control {
 ContextMenuStrip dropdown;
 public List<Choice> Items=new List<Choice>();int selected=-1;public event EventHandler SelectedIndexChanged;
 public int SelectedIndex {get{return selected;}set{selected=value;if(SelectedIndexChanged!=null)SelectedIndexChanged(this,EventArgs.Empty);Invalidate();}}
 public object SelectedItem {get{return selected>=0&&selected<Items.Count?Items[selected]:null;}}
 public ChoiceBox(){SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.AllPaintingInWmPaint,true);Cursor=Cursors.Hand;TabStop=true;Height=34;}
 protected override void OnClick(EventArgs e){base.OnClick(e);if(IsDisposed||Disposing||!Enabled)return;
  // Closed fires while ToolStrip is still unwinding selection and dismissal.
  // Keep the popup alive for the lifetime of its owning control.
  if(dropdown==null)dropdown=new ContextMenuStrip{BackColor=Color.White,ForeColor=ForeColor,ShowImageMargin=false};
  if(dropdown.Visible){dropdown.Close();return;}
  foreach(ToolStripItem old in dropdown.Items.Cast<ToolStripItem>().ToArray()){dropdown.Items.Remove(old);old.Dispose();}
  for(int i=0;i<Items.Count;i++){int index=i;var item=dropdown.Items.Add(Items[i].Text);item.Click+=(a,b)=>{if(!IsDisposed&&!Disposing&&index<Items.Count)SelectedIndex=index;};}
  dropdown.Show(this,new Point(0,Height));
 }
 protected override void Dispose(bool disposing){if(disposing&&dropdown!=null){dropdown.Dispose();dropdown=null;}base.Dispose(disposing);}
 protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Space||e.KeyCode==Keys.Enter)OnClick(EventArgs.Empty);if(e.KeyCode==Keys.Down)SelectedIndex=Math.Min(Items.Count-1,selected+1);if(e.KeyCode==Keys.Up)SelectedIndex=Math.Max(0,selected-1);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var shape=MotionButton.Rounded(new RectangleF(0,0,Width-1,Height-1),7))using(var brush=new SolidBrush(Color.White)){e.Graphics.FillPath(brush,shape);using(var pen=new Pen(Focused?Color.FromArgb(120,133,117):Color.FromArgb(220,221,216)))e.Graphics.DrawPath(pen,shape);}if(SelectedItem!=null)TextRenderer.DrawText(e.Graphics,SelectedItem.ToString(),Font,new Rectangle(10,0,Width-35,Height),ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(e.Graphics,"⌄",Font,new Rectangle(Width-25,0,20,Height),ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
}
