   bool fresh=target.Tag==null;target.Tag=row;
   string allocation=row.Rule!=null&&row.Rule.Enabled?row.Rule.Preset:row.Views.Count==0?"未运行":row.Views.Select(v=>v.Grant.Rule==null?"系统":v.Grant.Rule.Preset).Distinct().Count()>1?"混合":row.Views[0].Grant.Rule==null?"系统":row.Views[0].Grant.Rule.Preset;
