  }
  var selected=grid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>RowKey(r.Tag as AppRow).Equals(selection,StringComparison.OrdinalIgnoreCase));
  if(selected!=null&&!selected.Selected){grid.ClearSelection();selected.Selected=true;}
  var first=grid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>RowKey(r.Tag as AppRow).Equals(anchor,StringComparison.OrdinalIgnoreCase));
  if(grid.Rows.Count>0){int top=first!=null?first.Index:Math.Min(oldTop,grid.Rows.Count-1);if(grid.FirstDisplayedScrollingRowIndex!=top)grid.FirstDisplayedScrollingRowIndex=top;}
  if(grid.HorizontalScrollingOffset!=horizontal)grid.HorizontalScrollingOffset=horizontal;
