 void SaveRule(){if(string.IsNullOrWhiteSpace(path.Text))throw new Exception("先选择或添加一个程序。");var r=new Rule{Path=ApplicationGroups.IsGroup(path.Text)?path.Text:Path.GetFullPath(path.Text),Preset=Key(policy),Priority=Key(priority),Enabled=active.Checked&&Key(policy)!="Default",IncludeChildren=descendants.Checked,Mode="Hard",Cores=cores.CheckedIndices.Cast<int>().Select(i=>cpus[i].Key).ToArray()};if(r.Preset=="Custom"&&r.Cores.Length==0)throw new Exception("至少选择一个核心。");if(r.Preset=="Default"){r.Preset=CcdDiscovery.Default(config);r.IncludeChildren=false;}config.Rules.RemoveAll(x=>x.Path.Equals(r.Path,StringComparison.OrdinalIgnoreCase)||(ApplicationGroups.IsGroup(r.Path)&&ApplicationGroups.Contains(config,r.Path,x.Path)));config.DefaultExclusions=config.DefaultExclusions.Where(x=>!x.Equals(r.Path,StringComparison.OrdinalIgnoreCase)&&!(r.Path==ApplicationGroups.Codex&&ApplicationGroups.IsCodex(x))).ToArray();config.Rules.Add(r);SaveConfig();AppStore.Log("保存规则："+r.Path+" → "+(r.Enabled?r.Preset:"默认 "+CcdDiscovery.Default(config))+"；子进程="+r.IncludeChildren);var task=RefreshAsync();}
