 string ExplainLog(string line){if(line.Contains("失败")||line.Contains("无法恢复"))return "操作未完成，请查看原始错误信息。";if(line.Contains("已恢复隔离前设置"))return "已恢复该进程被管理前的 CPU 与优先级设置。";if(line.Contains("已校验"))return line.Contains("继承")?"已按启动程序的授权规则应用，并读回核对。":line.Contains("默认 CCD")?"已绑定默认 CPU 分组，并读回核对。":"已应用主动规则，并读回核对。";if(line.Contains("保存规则"))return "已保存程序规则。";if(line.Contains("删除主动规则"))return "已删除程序的主动授权。";return "未提供额外解释，请查看原始记录。";}
 void ReadLog(){if(logLoading||logGrid==null||logGrid.IsDisposed||page!=3)return;try{var file=Path.Combine(DataDir,"activity.log");var info=new FileInfo(file);if(!info.Exists){if(logLength<0){logGrid.Rows.Clear();logLength=0;}return;}long end=info.Length;DateTime creation=info.CreationTimeUtc,stamp=info.LastWriteTimeUtc;bool reset=logLength<0||end<logLength||creation!=logCreation;long start=reset?Math.Max(0,end-512*1024):logLength;if(!reset&&end==logLength&&stamp==logWrite)return;if(end-start>512*1024){reset=true;start=Math.Max(0,end-512*1024);}logLoading=true;var target=logGrid;Task.Run(()=>ReadLogRange(file,start,end,1000)).ContinueWith(t=>{try{if(IsDisposed||!IsHandleCreated)return;BeginInvoke(new Action(()=>{try{if(target.IsDisposed||page!=3)return;if(t.IsFaulted){AppStore.Log("读取活动记录失败："+t.Exception.GetBaseException().Message);return;}bool follow=target.Rows.Count==0||target.FirstDisplayedScrollingRowIndex<0||target.FirstDisplayedScrollingRowIndex+target.DisplayedRowCount(false)>=target.Rows.Count-1;rebuilding=true;if(reset)target.Rows.Clear();foreach(var line in t.Result)target.Rows.Add(line,ExplainLog(line));while(target.Rows.Count>1000)target.Rows.RemoveAt(0);if(follow&&target.Rows.Count>0)target.FirstDisplayedScrollingRowIndex=target.Rows.Count-1;logLength=end;logCreation=creation;logWrite=stamp;}catch(Exception ex){AppStore.Log("显示活动记录失败："+ex.Message);}finally{rebuilding=false;logLoading=false;}}));}catch{logLoading=false;}});}catch(Exception ex){logLoading=false;AppStore.Log("读取活动记录失败："+ex.Message);}}
 static string[] ReadLogRange(string file,long start,long end,int maximum){int count=(int)Math.Min(512*1024,Math.Max(0,end-start));var bytes=new byte[count];using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){stream.Position=start;int read=0;while(read<count){int n=stream.Read(bytes,read,count-read);if(n==0)break;read+=n;}if(read!=count)Array.Resize(ref bytes,read);}using(var memory=new MemoryStream(bytes,false))using(var reader=new StreamReader(memory,System.Text.Encoding.UTF8,true)){if(start>0)reader.ReadLine();var queue=new Queue<string>(Math.Min(maximum,256));string line;while((line=reader.ReadLine())!=null){if(queue.Count==maximum)queue.Dequeue();queue.Enqueue(line);}return queue.ToArray();}}
 async Task ExitCleanly(){if(closing||exitRequested)return;exitRequested=true;exitWasEnabled=config.IsolationEnabled;exitNoticeShown=false;timer.Stop();UpdateState();try{var result=await engine.StopAsync();if(result.PendingRecovery>0){config.IsolationEnabled=false;engine.Configure(config);UpdateExitProgress(result);timer.Start();if(!exitNoticeShown&&!silent){exitNoticeShown=true;Notice("正在等待恢复 "+result.PendingRecovery+" 个进程；每 5 秒重试一次。恢复完成后 CorePilot 会自动退出。点击“取消退出”可返回托盘监控。");}return;}CompleteExit();}catch(Exception ex){AppStore.Log("退出恢复失败，将继续重试："+ex);config.IsolationEnabled=false;engine.Configure(config);timer.Start();if(state!=null)state.Text="退出中 · 正在重试进程恢复";if(!exitNoticeShown&&!silent){exitNoticeShown=true;Notice("恢复过程暂时失败，CorePilot 会继续重试；恢复完成后自动退出。可以点击“取消退出”返回监控。");}}}
 void UpdateExitProgress(CycleResult result){if(result==null||!exitRequested)return;if(result.PendingRecovery<=0){CompleteExit();return;}if(state!=null&&!state.IsDisposed)state.Text="退出中 · 等待恢复 "+result.PendingRecovery+" 个进程；每 5 秒重试";}
 void CompleteExit(){if(closing)return;closing=true;exitRequested=false;timer.Stop();Close();}
 void CancelExit(){if(!exitRequested||closing)return;exitRequested=false;exitNoticeShown=false;config.IsolationEnabled=exitWasEnabled;if(config.IsolationEnabled)SchedulerEngine.Validate(config,cpus);SaveConfig();UpdateState();timer.Start();var refresh=RefreshAsync();}
 public static void InstallStartup(){var cpus=Native.Topology();var c=AppStore.Load(cpus);SchedulerEngine.Validate(c,cpus);StartupTask.Register(Application.ExecutablePath);c.IsolationEnabled=true;AppStore.Write(AppStore.FilePath,c);AppStore.Log("启用登录静默自启与默认 CCD1 策略");}
 [STAThread]public static void Main(string[] args){bool quiet=args.Contains("--silent");try{Application.EnableVisualStyles();if(args.Contains("--install-autostart")){InstallStartup();return;}if(args.Contains("--remove-autostart")){StartupTask.Remove();return;}if(args.Contains("--preview")){AppStore.TestDirectory=Path.Combine(Path.GetTempPath(),"CorePilot-preview-"+Guid.NewGuid().ToString("N"));var cpus=Native.Topology();var c=new Settings{CcdVerified=true,VerifiedFingerprint=AppStore.Fingerprint(cpus),CCD0=cpus.Where(x=>x.Cache==cpus[0].Cache).Select(x=>x.Key).ToArray(),CCD1=cpus.Where(x=>x.Cache!=cpus[0].Cache).Select(x=>x.Key).ToArray()};AppStore.Write(AppStore.FilePath,c);Application.Run(new CorePilot(false,true));return;}
  bool probe=args.Contains("--startup-probe");if(probe){AppStore.TestDirectory=Path.Combine(Path.GetTempPath(),"CorePilot-probe-"+Guid.NewGuid().ToString("N"));var c=AppStore.Load(Native.Topology());c.IsolationEnabled=false;AppStore.Write(AppStore.FilePath,c);}
  bool created;var single=new System.Threading.Mutex(true,"Local\\CorePilot-"+WindowsIdentity.GetCurrent().User.Value,out created);if(!created){single.Dispose();if(!quiet)MessageBox.Show("CorePilot 已在运行，请从托盘打开。");return;}if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)&&!probe)throw new Exception("请以管理员身份运行。");Native.EnableDebug();var app=new CorePilot(quiet);app.mutex=single;if(probe){var clock=new System.Windows.Forms.Timer{Interval=2000};clock.Tick+=async(s,e)=>{clock.Stop();File.WriteAllText(Path.Combine(AppStore.DirectoryPath,"startup-proof.txt"),"Visible="+app.Visible+"\r\nElevated="+new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)+"\r\nSession="+Process.GetCurrentProcess().SessionId);await app.ExitCleanly();clock.Dispose();};clock.Start();}Application.Run(app);
 }catch(Exception ex){AppStore.Log("启动失败："+ex);Environment.ExitCode=1;if(!quiet)MessageBox.Show(ex.Message,"CorePilot");}}
}


